{
  "id": "dsge-simple-model-eco",
  "name": "Simple DSGE Model",
  "description": "Illustrative three-variable New Keynesian adjustment model with exogenous expectations and an interest-rate rule. Smets and Wouters (2007) is conceptual background; this file is not their estimated stochastic DSGE model and does not reproduce its rational-expectations solution, seven shocks, frictions or fitted parameters.",
  "stocks": [
    {
      "id": "stock-output-gap",
      "name": "Output Gap",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-inflation",
      "name": "Inflation",
      "initial_value": 0.02,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-interest",
      "name": "Nominal Interest Rate",
      "initial_value": 0.04,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-output-change",
      "name": "Output Change",
      "equation": "(Expected_Output_Gap - Output_Gap - Sigma * (Nominal_Interest_Rate - Inflation - Natural_Rate)) / Adjustment_Time",
      "from_stock": null,
      "to_stock": "stock-output-gap",
      "position": {
        "x": 80,
        "y": 200
      }
    },
    {
      "id": "flow-inflation-change",
      "name": "Inflation Change",
      "equation": "(Beta * Expected_Inflation + Kappa * Output_Gap - Inflation) / Adjustment_Time",
      "from_stock": null,
      "to_stock": "stock-inflation",
      "position": {
        "x": 450,
        "y": 200
      }
    },
    {
      "id": "flow-interest-change",
      "name": "Interest Change",
      "equation": "(Taylor_Rate - Nominal_Interest_Rate) / Interest_Smoothing",
      "from_stock": null,
      "to_stock": "stock-interest",
      "position": {
        "x": 650,
        "y": 200
      }
    }
  ],
  "variables": [
    {
      "id": "var-taylor",
      "name": "Taylor Rate",
      "equation": "Natural_Rate + Target_Inflation + Phi_Pi * (Inflation - Target_Inflation) + Phi_Y * Output_Gap",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-natural",
      "name": "Natural Rate",
      "equation": "0.02",
      "position": {
        "x": 300,
        "y": 80
      }
    },
    {
      "id": "var-target",
      "name": "Target Inflation",
      "equation": "0.02",
      "position": {
        "x": 450,
        "y": 80
      }
    },
    {
      "id": "var-expected-y",
      "name": "Expected Output Gap",
      "equation": "0",
      "position": {
        "x": 600,
        "y": 80
      }
    },
    {
      "id": "var-expected-pi",
      "name": "Expected Inflation",
      "equation": "Target_Inflation",
      "position": {
        "x": 100,
        "y": 350
      }
    },
    {
      "id": "var-sigma",
      "name": "Sigma (Intertemporal Sub)",
      "equation": "1",
      "position": {
        "x": 300,
        "y": 350
      }
    },
    {
      "id": "var-beta",
      "name": "Beta (Discount)",
      "equation": "0.99",
      "position": {
        "x": 450,
        "y": 350
      }
    },
    {
      "id": "var-kappa",
      "name": "Kappa (Phillips Slope)",
      "equation": "0.1",
      "position": {
        "x": 600,
        "y": 350
      }
    },
    {
      "id": "var-phi-pi",
      "name": "Phi Pi",
      "equation": "1.5",
      "position": {
        "x": 100,
        "y": 420
      }
    },
    {
      "id": "var-phi-y",
      "name": "Phi Y",
      "equation": "0.5",
      "position": {
        "x": 250,
        "y": 420
      }
    },
    {
      "id": "var-smoothing",
      "name": "Interest Smoothing",
      "equation": "0.25",
      "position": {
        "x": 400,
        "y": 420
      }
    },
    {
      "id": "var-adjust-time",
      "name": "Adjustment Time",
      "equation": "0.25",
      "position": {
        "x": 550,
        "y": 420
      }
    },
    {
      "id": "var-real-rate",
      "name": "Real Interest Rate",
      "equation": "Nominal_Interest_Rate - Inflation",
      "position": {
        "x": 350,
        "y": 490
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Inflation",
      "to_element": "Taylor Rate"
    },
    {
      "id": "conn-2",
      "from_element": "Output Gap",
      "to_element": "Taylor Rate"
    },
    {
      "id": "conn-3",
      "from_element": "Output Gap",
      "to_element": "Inflation Change"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 40,
    "dt": 0.25
  },
  "created_at": "2026-01-12T07:45:54.017307+00:00",
  "updated_at": "2026-01-12T07:45:54.017314+00:00",
  "source": "https://doi.org/10.1257/aer.97.3.586",
  "reference": "Smets, F. and Wouters, R. (2007). Shocks and Frictions in US Business Cycles: A Bayesian DSGE Approach. American Economic Review 97(3):586-606. doi:10.1257/aer.97.3.586."
}

{
  "id": "predator-prey-allee-effect-eco",
  "name": "Predator-Prey with Allee Effect",
  "description": "Illustrative predator-prey model with a weak Allee factor N/(A+N) and saturating predation. The factor reduces per-capita prey growth at low density but does not create an intrinsic positive extinction threshold. Courchamp et al. (1999) is conceptual review background; the local equations and parameters are not an exact reproduction.",
  "source": "https://doi.org/10.1016/S0169-5347(99)01683-3",
  "reference": "Courchamp, F., Clutton-Brock, T. and Grenfell, B. (1999). Inverse density dependence and the Allee effect. Trends in Ecology & Evolution 14(10):405-410. doi:10.1016/S0169-5347(99)01683-3.",
  "stocks": [
    {
      "id": "stock-prey",
      "name": "Prey Population",
      "initial_value": 100,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-predator",
      "name": "Predator Population",
      "initial_value": 20,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-prey-birth",
      "name": "Prey Birth",
      "equation": "r * Prey_Population * Allee_Factor * (1 - Prey_Population / K)",
      "from_stock": null,
      "to_stock": "stock-prey",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "flow-predation",
      "name": "Predation",
      "equation": "a * Prey_Population * Predator_Population / (1 + a * h * Prey_Population)",
      "from_stock": "stock-prey",
      "to_stock": null,
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "flow-predator-birth",
      "name": "Predator Birth",
      "equation": "e * Predation",
      "from_stock": null,
      "to_stock": "stock-predator",
      "position": {
        "x": 300,
        "y": 200
      }
    },
    {
      "id": "flow-predator-death",
      "name": "Predator Death",
      "equation": "m * Predator_Population",
      "from_stock": "stock-predator",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 200
      }
    }
  ],
  "variables": [
    {
      "id": "var-allee",
      "name": "Allee Factor",
      "equation": "Prey_Population / (A + Prey_Population)",
      "position": {
        "x": 100,
        "y": 100
      }
    },
    {
      "id": "var-r",
      "name": "r",
      "equation": "0.5",
      "position": {
        "x": 100,
        "y": 300
      }
    },
    {
      "id": "var-k",
      "name": "K",
      "equation": "500",
      "position": {
        "x": 200,
        "y": 300
      }
    },
    {
      "id": "var-a-attack",
      "name": "a",
      "equation": "0.02",
      "position": {
        "x": 300,
        "y": 300
      }
    },
    {
      "id": "var-h",
      "name": "h",
      "equation": "0.1",
      "position": {
        "x": 400,
        "y": 300
      }
    },
    {
      "id": "var-e",
      "name": "e",
      "equation": "0.5",
      "position": {
        "x": 500,
        "y": 300
      }
    },
    {
      "id": "var-m",
      "name": "m",
      "equation": "0.2",
      "position": {
        "x": 600,
        "y": 300
      }
    },
    {
      "id": "var-allee-a",
      "name": "A",
      "equation": "20",
      "position": {
        "x": 200,
        "y": 100
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 0,
    "end": 100,
    "dt": 0.1
  },
  "created_at": "2026-01-11T21:45:15.068944+00:00",
  "updated_at": "2026-01-11T21:45:15.068944+00:00"
}

